import{a as e,i as t,r as n,t as r}from"./app-DllFuXBm.js";var i=JSON.parse(`{"path":"/guide/sauce.html","title":"搜图","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790405684000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"44ddac8ae97e55ade0c80cba0123eead160887e7","time":1790405684000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add sauce page, sync arcade prefixless and maimai updates"}]},"filePathRelative":"guide/sauce.md"}`),a={name:`sauce.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="搜图" tabindex="-1"><a class="header-anchor" href="#搜图"><span>搜图</span></a></h1><p>溯源一张图片的来源：找出它的画师、出处，或者是哪部番剧的截图。</p><h2 id="使用方式" tabindex="-1"><a class="header-anchor" href="#使用方式"><span>使用方式</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>sauce</code> / <code>搜图</code> / <code>识图</code></td><td>无（图片同条消息）</td><td>图片 + <code>.搜图</code> 同条发送</td><td>溯源本条消息中的第一张图片</td></tr><tr><td><code>sauce</code> / <code>搜图</code> / <code>识图</code></td><td><code>图片URL</code></td><td><code>.搜图 https://example.com/img.jpg</code></td><td>溯源指定直链图片</td></tr></tbody></table><div class="hint-container tip"><p class="hint-container-title">提示</p><p>图片必须和指令<strong>在同一条消息</strong>里发送（先贴图再打字会分成两条，不生效）。 也可以直接给图片直链，不用上传图片。</p></div><h2 id="返回内容" tabindex="-1"><a class="header-anchor" href="#返回内容"><span>返回内容</span></a></h2><ul><li>相似度、标题、作者与原始链接（最多 3 条）</li><li>附带最佳匹配的缩略图</li></ul><h2 id="数据源" tabindex="-1"><a class="header-anchor" href="#数据源"><span>数据源</span></a></h2><table><thead><tr><th>优先级</th><th>数据源</th><th>擅长</th></tr></thead><tbody><tr><td>主源</td><td>SauceNAO</td><td>插画 / 漫画（Pixiv、Danbooru 等索引）</td></tr><tr><td>备源</td><td>trace.moe</td><td>番剧截图识别（返回番剧名 / 集数 / 时间点）</td></tr></tbody></table><p>主源失败或无结果时自动降级到 trace.moe。</p><div class="hint-container warning"><p class="hint-container-title">注意</p><ul><li>必须带 <code>.</code> 前缀才会触发，不支持无前缀匹配</li><li>仅 QQ 群聊 / 私聊可用，QQ 官方渠道不解析收到的图片消息</li><li>SauceNAO 免费账户约 100 次/天、4 次/30 秒，请勿滥用</li><li>每人 30 秒冷却</li></ul></div>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};